INSERT INTO events(id,title,content,asset_id,status) VALUES('event-origins','原创世界开放日','探索黄金财神、龙腾四海与凤凰传奇三款原创演示。积分仅用于体验，无现金价值。','event-origins','published') ON CONFLICT(id) DO UPDATE SET asset_id=excluded.asset_id;
INSERT INTO events(id,title,content,asset_id,status) VALUES('event-dragon','龙珠探索之旅','认识5×3的243路计奖与本局龙珠共鸣奖励。完整规则见游戏帮助。','event-dragon','published') ON CONFLICT(id) DO UPDATE SET asset_id=excluded.asset_id;
INSERT INTO events(id,title,content,asset_id,status) VALUES('event-phoenix','见证凤凰涅槃','体验正交相邻五枚集群与重力补充，连消最多五轮。','event-phoenix','published') ON CONFLICT(id) DO UPDATE SET asset_id=excluded.asset_id;
INSERT INTO events(id,title,content,asset_id,status) VALUES('event-gems','独立美术图鉴','临时美术由AI原创生成；正式授权素材未来可通过后台逐张替换。','event-gems','published') ON CONFLICT(id) DO UPDATE SET asset_id=excluded.asset_id;
INSERT INTO events(id,title,content,asset_id,status) VALUES('event-stars','星曜开发日志','更多游戏正在筹备中。筹备条目没有启动入口，也不会扣除积分。','event-stars','published') ON CONFLICT(id) DO UPDATE SET asset_id=excluded.asset_id;
